TASK_NAME = "Send monthly usage reports (1st of each month, 09:10 IST)"


def create_monthly_report_schedule(apps, schema_editor):
    CrontabSchedule = apps.get_model("django_celery_beat", "CrontabSchedule")
    PeriodicTask = apps.get_model("django_celery_beat", "PeriodicTask")
    crontab, _ = CrontabSchedule.objects.get_or_create(
        minute="10", hour="9", day_of_week="*", day_of_month="1", month_of_year="*"
    )
    if not PeriodicTask.objects.filter(name=TASK_NAME).exists():
        PeriodicTask.objects.create(
            name=TASK_NAME, task="communication.send_monthly_usage_reports", crontab=crontab, enabled=True
        )


def remove_monthly_report_schedule(apps, schema_editor):
    PeriodicTask = apps.get_model("django_celery_beat", "PeriodicTask")
    PeriodicTask.objects.filter(name=TASK_NAME).delete()


